def solve(s0, done):
    # BFS; a state is only worth keeping if it has more bar left than any earlier visit with the same tile/key/rings
    best, q = {}, deque([(s0, "")])
    while q:
        s, path = q.popleft()
        if done(s):
            return path
        for m in "1234":
            n = step(s, m)
            if n is None:
                continue
            k = (n[0], n[1], n[3])
            if best.get(k, -1) >= n[2]:
                continue
            best[k] = n[2]
            q.append((n, path + m))
    return None

