    for r in range(55):
        for j in range(NJ):
            c = C0 + TS * j
            if board[r][c:c + TS] == "wwwww":
                i = (r - R0) // TS
                out[(i + 1, j) if (r - R0) % TS == TS - 1 else (i - 1, j)] = "wbar"
    for c in range(64):
        for i in range(NI):
            r = R0 + TS * i
            if all(board[r + a][c] == "w" for a in range(TS)):
                j = (c - C0) // TS
